import csv
import re


_AMOUNT_PATTERN = re.compile(r"[+-]?\d+(?:[.,]\d+)?\Z")


def parse_invoices(text):
    reader = csv.reader(text.splitlines(), delimiter=";", strict=True)
    try:
        header = next(reader)
    except (StopIteration, csv.Error) as exc:
        raise ValueError("missing or invalid header") from exc

    if header != ["id", "amount"]:
        raise ValueError("header must be exactly 'id;amount'")

    invoices = []
    try:
        for row in reader:
            if not row or (len(row) == 1 and not row[0].strip()):
                continue
            if len(row) != 2:
                raise ValueError("each record must contain exactly two fields")

            identifier, amount = (field.strip() for field in row)
            if not identifier or not amount:
                raise ValueError("id and amount must not be empty")
            if not _AMOUNT_PATTERN.fullmatch(amount):
                raise ValueError("invalid amount")

            invoices.append({"id": identifier, "amount": amount.replace(",", ".")})
    except csv.Error as exc:
        raise ValueError("invalid CSV data") from exc

    return invoices
